const iconPaths={dashboard:'M3 3h7v7H3zM14 3h7v4h-7zM14 11h7v10h-7zM3 14h7v7H3z',upload:'M12 16V4m0 0L7 9m5-5 5 5M4 20h16',alert:'M12 9v4m0 4h.01M10.3 3.8 2.4 17.5A2 2 0 0 0 4.1 20h15.8a2 2 0 0 0 1.7-2.5L13.7 3.8a2 2 0 0 0-3.4 0Z',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m7-10a4 4 0 1 0 0-8 4 4 0 0 0 0 8m13 10v-2a4 4 0 0 0-3-3.9m0-7.8a4 4 0 0 1 0 7.7',play:'M8 5v14l11-7z',table:'M4 4h16v16H4zM4 9h16M9 4v16',calculator:'M6 3h12v18H6zM8.5 6h7v3h-7zM9 13h.01m3 0h.01m3 0h.01M9 17h.01m3 0h.01m3 0h.01',check:'M20 6 9 17l-5-5',file:'M6 2h9l5 5v15H6zM14 2v6h6M9 13h6m-6 4h6',book:'M4 19.5A2.5 2.5 0 0 1 6.5 17H20V3H6.5A2.5 2.5 0 0 0 4 5.5zM4 5.5V20',calendar:'M3 5h18v16H3zM7 3v4m10-4v4M3 10h18',clock:'M12 22a10 10 0 1 0 0-20 10 10 0 0 0 0 20m0-15v5l3 2',chart:'M4 20V10m6 10V4m6 16v-7m5 7H2'};
