    function renderNav(){nav.innerHTML=groups.map(g=>`<div><div class="nav-label">${g[0]}</div>${g[1].map(i=>`<button class="nav-item ${i[1]===active?'active':''}" ${i[3]?`disabled aria-disabled="true" title="${i[4]}"`:`data-page="${i[1]}"`}>${svg(i[0])}<span>${i[1]}</span>${i[2]?`<b class="nav-badge">${i[2]}</b>`:''}</button>`).join('')}</div>`).join('')}
    const head=(title,desc,actions='')=>`<div class="page-head"><div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;
    const button=(text,kind='primary',action='demo')=>`<button class="btn ${kind}" data-action="${action}">${text}</button>`;
    const person=(name,initials)=>`<div class="person"><div class="avatar">${initials}</div><div><strong>${name}</strong></div></div>`;
    /* Year-to-date 13th-month accrual. The launch system holds no payroll
       history, so the figure is estimated from each employee's start date and
       current basic salary rather than from basic salary actually earned:
       (monthly basic x months accrued) / 12. Months accrue from January, or
       from the start date where the employee joined during the current year.
       Employees with no start date are excluded and reported separately so a
       missing date is never read as a zero accrual. */
    const asOf={year:2026,month:8};
    const thirteenthRoster=[
      {name:'Mara Santos',start:'2019-03-11',basic:44000},
      {name:'Paolo Reyes',start:'2021-07-01',basic:38000},
      {name:'Nina Garcia',start:'2026-04-16',basic:31000},
      {name:'Carlo Mendoza',start:'2017-01-09',basic:52000},
      {name:'Lea Villanueva',start:'2026-02-01',basic:36000},
      {name:'Alex Rivera',start:null,basic:28000}
    ];
    /* Whole months of service inside the current calendar year, up to and
       including the month being reported. A mid-year joiner accrues only from
       their start month, so the estimate is pro-rated rather than full-year. */
    function accrualMonths(startDate,at=asOf){
      const start=new Date(`${startDate}T00:00:00`);
      if(Number.isNaN(start.getTime()))return null;
      if(start.getFullYear()>at.year)return 0;
      const firstMonth=start.getFullYear()===at.year?start.getMonth()+1:1;
      return Math.max(0,at.month-firstMonth+1);
    }
    function thirteenthAccrual(roster=thirteenthRoster,at=asOf){
      let total=0,counted=0,proRated=0;const missingStartDate=[];
      roster.forEach(e=>{
        const months=e.start?accrualMonths(e.start,at):null;
        if(months===null){missingStartDate.push(e.name);return}
        total+=(Number(e.basic)||0)*months/12;
        counted++;
        if(new Date(`${e.start}T00:00:00`).getFullYear()===at.year)proRated++;
      });
      return{total,counted,proRated,missingStartDate};
    }
    const compactPeso=value=>value>=1e6?`₱${(value/1e6).toFixed(2)}M`:value>=1e3?`₱${(value/1e3).toFixed(1)}K`:peso(value);
    function thirteenthTile(){
      const a=thirteenthAccrual();
      const missing=a.missingStartDate.length;
      const foot=missing
        ? `<span class="delta down">${missing} without a start date</span> · excluded from the estimate`
        : `Pro-rated for ${a.proRated} employee${a.proRated===1?'':'s'} who joined this year`;
      return{label:'13th-month accrual',icon:'calculator',value:compactPeso(a.total),estimate:true,foot:`Forecast to Dec · ${foot}`};
    }
    /* Dashboard summary tiles grouped by period. Tiles that only apply to one
       period (active employees, employees in run) live in that row alone. */
    const kpiPeriods=[
      {id:'ytd',label:'Year to date',range:'01 Jan – 20 Aug 2026',tiles:[
        {label:'Active employees',icon:'people',value:'131',foot:'<span class="delta">+7</span> net movement this year'},
        {label:'Employees in run',icon:'check',value:'124',foot:'<span class="delta">+3</span> since last cut-off'},
        {label:'Gross payroll',icon:'peso',value:'₱58.12M',foot:'<span class="delta">+6.4%</span> vs same period 2025'},
        {label:'Net payroll',icon:'peso',value:'₱51.16M',foot:'88.0% of gross payroll'},
        {label:'Withholding taxes',icon:'table',value:'₱4.31M',foot:'Employer + employee total'},
        {label:'Social contributions',icon:'table',value:'₱2.65M',foot:'Employer + employee total'},
        thirteenthTile()
      ]},
      {id:'mtd',label:'Month to date',range:'01 – 20 Aug 2026',tiles:[
        {label:'Gross payroll',icon:'peso',value:'₱3.84M',foot:'<span class="delta">+2.8%</span> vs previous cut-off'},
        {label:'Net payroll',icon:'peso',value:'₱3.38M',foot:'88.0% of gross payroll'},
        {label:'Withholding taxes',icon:'table',value:'₱286.4K',foot:'Employer + employee total'},
        {label:'Social contributions',icon:'table',value:'₱174.8K',foot:'Employer + employee total'}
      ]}
    ];
    const kpiTile=t=>`<div class="card kpi${t.estimate?' kpi-estimate':''}"><div class="kpi-top"><span>${t.label}</span><span class="kpi-icon">${t.icon==='peso'?'₱':svg(t.icon)}</span></div><div class="kpi-value">${t.value}${t.estimate?'<span class="pill amber estimate-tag">Estimate</span>':''}</div><div class="kpi-foot">${t.foot}</div></div>`;
    const kpiBand=p=>`<section class="kpi-band" aria-labelledby="kpi-${p.id}"><div class="kpi-band-head"><h2 class="kpi-band-label" id="kpi-${p.id}">${p.label}</h2><span class="kpi-band-range">${p.range}</span></div><div class="grid kpis" data-count="${p.tiles.length}">${p.tiles.map(kpiTile).join('')}</div></section>`;
    function overview(){return head('Payroll control centre','Upload the CTS timesheet, run the workbook-based computations, generate payslips and send them automatically by email.',button('Continue payroll run','teal','go-run'))+`
      <div class="kpi-periods">${kpiPeriods.map(kpiBand).join('')}</div>
      <div class="grid dashboard-grid">
        <div class="stack">
          <section class="card hero-card"><div class="hero-top"><div><span class="eyebrow" style="color:#d7e035">Active payroll run</span><h2>06–20 Aug 2026</h2><p>Workbook formulas are being applied</p></div><div class="hero-meta"><strong>54% complete</strong><small>Last updated 8 min ago</small></div></div><div class="progress-track"><div class="progress-fill"></div></div><div class="steps"><div class="step done">Uploaded</div><div class="step done">Validated</div><div class="step current">Computed</div><div class="step">Payslips</div><div class="step">Email</div></div></section>
          <section class="card section-card"><div class="card-head"><div><div class="card-title">Payroll readiness</div><div class="card-sub">Inputs and formulas required before payslip generation</div></div><button class="text-link" data-page="Payroll run">Open run →</button></div><div class="table-wrap"><table><thead><tr><th>Control</th><th>Source</th><th>Result</th><th>Last checked</th></tr></thead><tbody><tr><td>Timesheet workbook</td><td>Uploaded file</td><td><span class="pill green">Complete</span></td><td class="muted">09:42</td></tr><tr><td>Employee rows matched</td><td>Workbook</td><td><span class="pill green">124 matched</span></td><td class="muted">09:44</td></tr><tr><td>Computation formulas</td><td>CTS workbook</td><td><span class="pill green">Loaded</span></td><td class="muted">09:45</td></tr><tr><td>Government tables</td><td>Rule book</td><td><span class="pill amber">Verify when updated</span></td><td class="muted">Yesterday</td></tr></tbody></table></div></section>
        </div>
        <div class="stack">
          <section class="card section-card"><div class="card-head"><div><div class="card-title">Processing status</div><div class="card-sub">Upload, computation and delivery checks</div></div></div><div class="mini-list"><div class="issue"><div class="issue-icon" style="background:var(--green-bg);color:var(--green)">✓</div><div><strong>Timesheet uploaded</strong><small>2,846 rows accepted</small></div><span class="count">Complete</span></div><div class="issue"><div class="issue-icon" style="background:var(--amber-bg);color:var(--amber)">ƒ</div><div><strong>Payroll computation</strong><small>Workbook formulas applied</small></div><span class="count">Running</span></div><div class="issue"><div class="issue-icon" style="background:#e7f2f6;color:#285f78">✉</div><div><strong>Payslip email delivery</strong><small>Queued after generation</small></div><span class="count">Next</span></div></div></section>
          <section class="card section-card"><div class="card-head"><div><div class="card-title">Payroll cost trend</div><div class="card-sub">Gross pay · last 8 cut-offs</div></div><strong class="money">₱3.84M</strong></div><div class="chart-wrap">${[58,64,61,69,66,73,70,81].map((h,i)=>`<div class="bar ${i===7?'active':''}" style="height:${h}%"><span class="bar-label">${i%2?'30th':'15th'}</span></div>`).join('')}</div></section>
        </div>
      </div>`}
    function timesheets(){const rows=[['2,841','Mara Santos','CTS-0104','06–20 Aug','176.0 h','Matched'],['2,842','Paolo Reyes','CTS-0089','06–20 Aug','168.0 h','Matched'],['2,843','Nina Garcia','CTS-0121','06–20 Aug','92.5 h','Matched'],['2,844','J. Dela Cruz','—','06–20 Aug','80.0 h','Unmatched'],['2,845','Carlo Mendoza','CTS-0048','06–20 Aug','184.0 h','Matched'],['2,846','M. Santos','—','06–20 Aug','8.0 h','Duplicate']];return head('Timesheet import','Bring attendance into the cut-off in one controlled step. Original TCW values remain intact for audit.',button('Pull automatically','','auto-pull')+button('Commit import','teal','commit-import'))+`<div class="split"><section class="card panel"><div class="upload"><div class="upload-icon">${svg('upload')}</div><h3>Drop TCW attendance here</h3><p>CSV or Excel · one file for all client accounts · maximum 25 MB</p>${button('Choose file','','choose')}</div></section><aside class="card panel"><div class="card-title">Cut-off assignment</div><div class="card-sub">Applied to every valid imported row</div><div style="height:14px"></div><div class="field"><label>Cut-off period</label><select><option>06–20 Aug 2026</option></select></div><div style="height:12px"></div><div class="field"><label>Client account</label><select><option>All accounts</option><option>Future Analytics</option></select></div><div style="height:12px"></div><label style="font-size:11px;color:var(--ink-2)"><input type="checkbox"> Overwrite existing rows</label></aside></div><div style="height:16px"></div><div class="grid kpis"><div class="card kpi"><div class="kpi-top">Rows read</div><div class="kpi-value">2,846</div><div class="kpi-foot">One cut-off export</div></div><div class="card kpi"><div class="kpi-top">Matched</div><div class="kpi-value">2,842</div><div class="kpi-foot"><span class="delta">99.9%</span> assigned</div></div><div class="card kpi"><div class="kpi-top">Unmatched</div><div class="kpi-value">2</div><div class="kpi-foot"><span class="delta down">Action required</span></div></div><div class="card kpi"><div class="kpi-top">Duplicates</div><div class="kpi-value">2</div><div class="kpi-foot">Held from commit</div></div></div><section class="card panel"><div class="tabs"><button class="tab active">All rows</button><button class="tab">Unmatched <span class="pill red">2</span></button><button class="tab">Matched</button><button class="tab">Duplicates <span class="pill amber">2</span></button></div><div class="table-wrap"><table><thead><tr><th>Row</th><th>Employee</th><th>Employee ID</th><th>Cut-off</th><th>Total hours</th><th>Match</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td class="money">${r[0]}</td><td><strong>${r[1]}</strong></td><td class="money">${r[2]}</td><td>${r[3]}</td><td class="money">${r[4]}</td><td><span class="pill ${r[5]==='Matched'?'green':r[5]==='Duplicate'?'amber':'red'}">${r[5]}</span></td><td><button class="text-link" data-action="import-row">Open →</button></td></tr>`).join('')}</tbody></table></div></section>`}
    const exceptionRows=[['Missing clock-out','Mara Santos','04 Sep · Night shift','Critical'],['Unmatched employee','J. Dela Cruz','03 Sep · TCW import','Critical'],['Missing break punch','Paolo Reyes','02 Sep · Day shift','Review'],['17.4-hour duration','Nina Garcia','01 Sep · Night shift','Review'],['Duplicate row','Carlo Mendoza','29 Aug · TCW import','Review']];
    function exceptions(){return head('Exception queue','Resolve incomplete and implausible attendance before payroll. Every correction keeps the imported value beside it.',button('Export queue','','export'))+`<div class="toolbar"><div class="filters"><input class="search" placeholder="Search employee or issue"><select class="select"><option>All severity</option><option>Critical</option><option>Review</option></select><select class="select"><option>All client accounts</option><option>Future Analytics</option><option>Northstar Retail</option></select></div><span class="muted">7 open · 2 resolved today</span></div><section class="card table-card"><div class="table-wrap"><table><thead><tr><th>Issue</th><th>Employee</th><th>Attendance record</th><th>Severity</th><th></th></tr></thead><tbody>${exceptionRows.map(r=>`<tr><td><strong>${r[0]}</strong></td><td>${r[1]}</td><td class="muted">${r[2]}</td><td><span class="pill ${r[3]==='Critical'?'red':'amber'}">${r[3]}</span></td><td>${button('Resolve','','resolve')}</td></tr>`).join('')}</tbody></table></div></section>`}
    const employees=[['Mara Santos','MS','CTS-0104','Future Analytics','Full time','Active'],['Paolo Reyes','PR','CTS-0089','Northstar Retail','Full time','Active'],['Nina Garcia','NG','CTS-0121','Future Analytics','Part time','Active'],['Carlo Mendoza','CM','CTS-0048','Aster Health','Full time','Active'],['Lea Villanueva','LV','CTS-0117','Northstar Retail','Full time','On leave']];
