    function register(){return head('Payroll register','Review per-employee gross, deductions and net pay with variance against the previous cut-off.',button('Submit for approval','teal','submit-approval'))+`<div class="grid kpis" style="grid-template-columns:repeat(3,1fr)"><div class="card kpi"><div class="kpi-top">Gross pay</div><div class="kpi-value">₱3.84M</div><div class="kpi-foot"><span class="delta">+2.8%</span> vs previous cut-off</div></div><div class="card kpi"><div class="kpi-top">Total deductions</div><div class="kpi-value">₱461.2K</div><div class="kpi-foot">12.0% of gross payroll</div></div><div class="card kpi"><div class="kpi-top">Net pay</div><div class="kpi-value">₱3.38M</div><div class="kpi-foot">124 employees</div></div></div><div class="toolbar"><div class="filters"><input class="search" placeholder="Search employee"><select class="select"><option>All variance</option><option>Over ±10%</option></select></div><span class="muted">Showing 5 of 124</span></div><section class="card table-card"><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Paid hours</th><th>Gross</th><th>Deductions</th><th>Net pay</th><th>Variance</th><th></th></tr></thead><tbody>${registerRows.map(r=>`<tr><td>${person(r[0],r[1])}</td><td class="money">${r[2]}</td><td class="money">${r[3]}</td><td class="money">${r[4]}</td><td class="money">${r[5]}</td><td><span class="pill ${Math.abs(parseFloat(r[6]))>10?'amber':'gray'}">${r[6]}</span></td><td><button class="text-link" data-action="breakdown">Details →</button></td></tr>`).join('')}</tbody></table></div></section>`}
    function approvals(){return head('Run approval','An independent review before anything is released. The approved run becomes immutable.',button('Approve run','teal','approve')+button('Reject with reason','danger','reject'))+`<div class="split"><section class="card panel"><div class="card-head"><div><div class="card-title">06–20 Aug 2026</div><div class="card-sub">Submitted by Reg A. · 06 Sep 2026, 14:28</div></div><span class="pill amber">Awaiting approval</span></div><div class="alert-box"><span>!</span><div><strong>One material variance needs acknowledgement</strong><p>Nina Garcia is 12.1% above the previous cut-off due to approved night differential and overtime.</p></div></div><div style="height:16px"></div><div class="summary-row"><span>Employees</span><strong>124</strong></div><div class="summary-row"><span>Gross payroll</span><strong>₱3,842,640.18</strong></div><div class="summary-row"><span>Deductions</span><strong>₱461,174.32</strong></div><div class="summary-row"><span>Net payroll</span><strong>₱3,381,465.86</strong></div></section><aside class="card panel"><div class="card-title">Approval checklist</div><div style="height:13px"></div>${['Exception queue cleared','Register reviewed','Variance report reviewed','Rule versions verified','Disbursement control total matched'].map((x,i)=>`<label class="summary-row"><span>${x}</span><input type="checkbox" ${i<3?'checked':''}></label>`).join('')}</aside></div>`}
    function payslips(){const isEom=payslipCutoff==='EOM';const premiums=isEom?[['ND','22.00','₱355.38'],['REG OT','—','—'],['REG OTND','—','—'],['RD OT','—','—'],['RD OTND','—','—'],['RD Excess','—','—'],['SH','—','—'],['SH ND','—','—'],['SH OT','—','—'],['RD SH','—','—'],['RD SH ND','—','—'],['RD SH Excess','—','—'],['RH','—','—'],['RH ND','—','—'],['RH OT','—','—'],['RD RH','—','—'],['RD RH ND','—','—'],['RD RH Excess','—','—'],['Other','—','—']]:[['ND','—','—'],['REG OT','—','—'],['REG OTND','—','—'],['RD OT','—','—'],['RD OTND','—','—'],['RD Excess','—','—'],['SH','—','—'],['SH ND','—','—'],['SH OT','—','—'],['RD SH','—','—'],['RD SH ND','—','—'],['RD SH Excess','—','—'],['RH','—','—'],['RH ND','—','—'],['RH OT','—','—'],['RD RH','—','—'],['RD RH ND','—','—'],['RD RH Excess','—','—'],['Other','—','—']];const pay=isEom?{period:'06–20 Aug 2026',date:'31 Aug 2026',other:'₱355.38',gross:'₱14,355.38',taxable:'₱13,205.38',tax:'−₱418.41',subtotal:'₱12,786.97',extra:'<div class="pay-row"><span>Wellness Allowance</span><span></span><span class="amount">₱1,000.00</span></div>',nonTax:'₱2,800.00',net:'₱15,586.97'}:{period:'21 Jul–05 Aug 2026',date:'15 Aug 2026',other:'—',gross:'₱14,000.00',taxable:'₱12,850.00',tax:'−₱364.95',subtotal:'₱12,485.05',extra:'<div class="pay-row"><span>HDMF Loan</span><span></span><span class="amount">−₱600.00</span></div>',nonTax:'₱1,200.00',net:'₱13,685.05'};return head('Payslip release','Preview both workbook-defined cutoff outputs before the approved run is released.',button('Release 124 payslips','teal','release'))+`<div class="source-banner"><div class="source-mark">X</div><div><strong>Calculation structure follows the CTS-provided workbook</strong><p>Labels, cutoff treatment, contribution splitting and EOM tax reconciliation follow the workbook.</p></div></div><div class="split payslip-layout"><section class="card panel"><div class="card-head"><div><div class="card-title">Delivery status</div><div class="card-sub">${payslipCutoff} cut-off · release blocked until approval</div></div><span class="pill gray">Not released</span></div><div class="workbook-tabs"><button class="btn ${!isEom?'active':''}" data-action="payslip-15th">15th output</button><button class="btn ${isEom?'active':''}" data-action="payslip-eom">EOM output</button></div><div class="summary-row"><span>Workbook source sheet</span><strong>${isEom?'RAW EOM → EOM':'RAW 15th → 15th'}</strong></div><div class="summary-row"><span>Ready to generate</span><strong>124</strong></div><div class="summary-row"><span>Generated</span><strong>124</strong></div><div class="summary-row"><span>Delivered</span><strong>0</strong></div><div style="height:14px"></div><div class="alert-box"><span>i</span><div><strong>${isEom?'Monthly tax reconciliation':'Semi-monthly tax calculation'}</strong><p>${isEom?'EOM combines taxable income from both cutoffs, calculates monthly tax, then deducts tax already withheld on the 15th.':'The first cutoff uses the workbook semi-monthly withholding table. The amount is carried into the EOM reconciliation.'}</p></div></div><div style="height:14px"></div>${button('Preview PDF','','preview')}${button('Select employee','','select-payslip')}</section><aside class="card panel"><div class="card-head"><div><div class="card-title">CTS payslip preview · ${payslipCutoff}</div><div class="card-sub">Employee payslip</div></div><span class="pill blue">Page 1 of 1</span></div><div class="payslip-paper"><div class="payslip-brand"><div class="payslip-branding"><img class="payslip-logo" src="cts-logo-outlined.png" alt="CTS logo"><small>${isEom?'End-of-month':'15th'} employee payslip</small></div></div><div class="payslip-body"><div class="payslip-meta"><span>Employee</span><strong>Alex Rivera</strong><span>Position</span><strong>Quality Support Specialist</strong><span>Employment type</span><strong>Northstar Services – Regular</strong><span>Cut-off date</span><strong>${pay.period}</strong><span>Pay-out date</span><strong>${pay.date}</strong><span>Monthly rate</span><strong>₱28,000.00</strong><span>Hourly rate</span><strong>₱161.54</strong></div><div class="pay-head"><span>HRS type</span><span style="text-align:right">Hours</span><span style="text-align:right">Amount</span></div><div class="pay-row"><span>${isEom?'Regular Hours':'Scheduled Hours'}</span><span class="hours">88.00</span><span class="amount">₱14,000.00</span></div><div class="pay-row"><span>Adjustment</span><span class="hours">—</span><span class="amount">—</span></div><div class="pay-row"><span>Absences</span><span class="hours">—</span><span class="amount">—</span></div><div class="pay-row"><span>Tardiness / UT / OB</span><span class="hours">—</span><span class="amount">—</span></div><div class="pay-row total"><span>Total Basic Hours</span><span class="hours">88.00</span><span class="amount">₱14,000.00</span></div>${premiums.map(r=>`<div class="pay-row"><span>${r[0]}</span><span class="hours">${r[1]}</span><span class="amount">${r[2]}</span></div>`).join('')}<div class="pay-row total"><span>Total Other Income</span><span></span><span class="amount">${pay.other}</span></div><div class="pay-row"><span>Gross Income</span><span></span><span class="amount">${pay.gross}</span></div><div class="pay-group">Statutory deductions</div><div class="pay-row"><span>SSS</span><span></span><span class="amount">−₱700.00</span></div><div class="pay-row"><span>HDMF</span><span></span><span class="amount">−₱100.00</span></div><div class="pay-row"><span>PhilHealth</span><span></span><span class="amount">−₱350.00</span></div><div class="pay-row subtotal"><span>Net Taxable Income</span><span></span><span class="amount">${pay.taxable}</span></div><div class="pay-row"><span>Tax</span><span></span><span class="amount">${pay.tax}</span></div><div class="pay-row subtotal"><span>Sub Total</span><span></span><span class="amount">${pay.subtotal}</span></div><div class="pay-group">Non-tax income</div><div class="pay-row"><span>NonTax Allowance</span><span></span><span class="amount">₱1,800.00</span></div>${pay.extra}<div class="pay-row total"><span>Total Non-Tax Income</span><span></span><span class="amount">${pay.nonTax}</span></div><div class="pay-row net"><span>Net Pay</span><span></span><span class="amount">${pay.net}</span></div><div class="payslip-note">Calculations follow the CTS payroll workbook.</div></div></div></aside></div>`}
    const peso=value=>new Intl.NumberFormat('en-PH',{style:'currency',currency:'PHP',minimumFractionDigits:2}).format(Number(value)||0).replace('PHP','₱');
    function thirteenthMonth(){return head('13th-month pay','Manually review the employee’s calendar-year basic salary and prepare the statutory 13th-month amount.',button('Add to December payroll','teal','save-13th'))+`<div class="thirteenth-layout"><section class="card panel"><div class="calc-intro"><div class="rule-icon">${svg('calculator')}</div><div><strong>Philippine statutory minimum</strong><p>For covered private-sector rank-and-file employees: total basic salary earned during the calendar year ÷ 12. Payment is due no later than December 24. <a href="https://bwc.dole.gov.ph/dole-bwc-urges-employers-to-release-13th-month-pay-not-later-than-december-24/" target="_blank" rel="noreferrer">DOLE reference ↗</a></p></div></div><div class="card-head"><div><div class="card-title">Manual calculation details</div><div class="card-sub">Review and edit the salary details</div></div><span class="pill blue">Manual review</span></div><div class="form-grid"><div class="field"><label>Employee</label><select id="thirteenthEmployee"><option>Alex Rivera · CTS-0142</option><option>Jamie Cruz · CTS-0108</option></select></div><div class="field"><label>Calendar year</label><select id="thirteenthYear"><option>2026</option><option>2025</option></select></div><div class="field"><label>Total basic salary earned</label><input id="thirteenthBase" type="number" min="0" step="0.01" value="336000" aria-describedby="basicSalaryHelp"></div><div class="field"><label>Other benefits using ₱90,000 ceiling</label><input id="thirteenthOther" type="number" min="0" step="0.01" value="12000" aria-describedby="otherBenefitsHelp"></div></div><div class="definition-list"><div class="definition-item"><i>✓</i><div><strong>Enter basic salary actually earned</strong><small id="basicSalaryHelp">Use the employee’s basic salary paid for services during the year, including only items CTS treats as part of basic salary under policy or agreement.</small></div></div><div class="definition-item"><i>–</i><div><strong>Normally excluded from the salary base</strong><small>Allowances, overtime, premium pay, night differential, holiday pay and unused-leave conversions, unless CTS policy or an agreement treats an item as basic salary.</small></div></div><div class="definition-item"><i>₱</i><div><strong>Tax ceiling uses combined benefits</strong><small id="otherBenefitsHelp">Enter other benefits that share the current ₱90,000 income-tax exemption ceiling with 13th-month pay.</small></div></div></div><label class="calc-check"><input id="thirteenthReviewed" type="checkbox"><span>I reviewed the salary base, employee coverage and CTS policy before adding this amount to payroll.</span></label><div class="calc-actions">${button('Recalculate','primary','calculate-13th')}<span class="muted" style="font-size:10px">Nothing is posted until the reviewed entry is added.</span></div></section><aside class="stack"><section class="calc-result"><span class="eyebrow">Calculated 13th-month pay</span><div class="calc-total" id="thirteenthTotal">₱28,000.00</div><div class="calc-formula" id="thirteenthFormula">₱336,000.00 ÷ 12</div><div class="result-row"><span>Current combined exemption ceiling</span><strong id="thirteenthCeiling">₱90,000.00</strong></div><div class="result-row"><span>Combined taxable excess</span><strong id="thirteenthTaxable">₱0.00</strong></div><div class="result-row"><span>13th month + other benefits</span><strong id="thirteenthCombined">₱40,000.00</strong></div><div class="policy-note"><strong>Tax note</strong><br>The ₱90,000 ceiling applies to 13th-month pay together with qualifying “other benefits.” Any combined excess is treated as taxable compensation. Verify the ceiling when government rules change.</div></section><section class="card panel"><div class="card-title">How this step fits payroll</div><div class="card-sub">A controlled adjustment before payslip generation</div><div style="height:10px"></div><div class="summary-row"><span>1 · Review YTD basic salary</span><strong>Manual</strong></div><div class="summary-row"><span>2 · Calculate statutory minimum</span><strong>Automatic</strong></div><div class="summary-row"><span>3 · Confirm tax classification</span><strong>Review</strong></div><div class="summary-row"><span>4 · Add to December payroll</span><strong>Pending</strong></div></section></aside></div>`}
    function updateThirteenth(){const base=Math.max(0,Number(document.getElementById('thirteenthBase')?.value)||0);const other=Math.max(0,Number(document.getElementById('thirteenthOther')?.value)||0);const total=base/12;const combined=total+other;const taxable=Math.max(0,combined-90000);document.getElementById('thirteenthTotal').textContent=peso(total);document.getElementById('thirteenthFormula').textContent=`${peso(base)} ÷ 12`;document.getElementById('thirteenthCeiling').textContent=peso(90000);document.getElementById('thirteenthTaxable').textContent=peso(taxable);document.getElementById('thirteenthCombined').textContent=peso(combined);return{total,taxable}}
    const rules=[['Premium multipliers','ND 10%; OT 125%; rest day 130%; special-holiday and regular-holiday combinations follow the workbook columns.','Workbook formulas','In use',false],['SSS contributions','Salary-range lookup from the workbook contribution schedule; employee share is split across both cutoffs.','A14:J74','Verification required',true],['PhilHealth','Workbook formula applies 5% with employee and cutoff splitting.','Workbook formula','Verification required',true],['HDMF / Pag-IBIG','Workbook deducts ₱100 per cutoff when statutory deductions apply.','₱100 / cutoff','Verification required',true],['Withholding tax','15th uses the semi-monthly table. EOM calculates monthly tax on both cutoffs and subtracts 15th tax.','A2:J7','Verification required',true],['CTS payroll policy','Monthly rate ÷ 2 for basic cutoff pay above the workbook threshold; adjustments and non-tax items follow workbook fields.','RAW sheet logic','Client-provided',false]];
    function rulebook(){return head('Rule book','Calculation logic derived from the workbook, with regulatory tables identified for verification.',button('+ New rule version','teal','new-rule'))+`<div class="source-banner"><div class="source-mark">X</div><div><strong>Source workbook · CTS payroll workbook 2026</strong><p>Calculations follow the client-provided workbook. Verification flags identify rules that must be confirmed before use.</p></div></div><div class="toolbar"><div class="filters"><button class="btn primary">Workbook rules</button><button class="btn">Statutory tables</button><button class="btn">CTS policy</button></div><span class="pill blue">Reference snapshot</span></div><div class="rule-grid">${rules.map((r,i)=>`<article class="rule-card ${r[4]?'flagged':''}">${r[4]?'<span class="pill amber">Future verification</span>':'<span class="pill green">Workbook confirmed</span>'}<div class="rule-icon">${svg(i<1?'clock':i<5?'table':'book')}</div><h3>${r[0]}</h3><p>${r[1]}</p><div class="rule-meta"><span>${r[2]}</span><strong>${r[3]}</strong></div></article>`).join('')}</div><div style="height:16px"></div><section class="card panel"><div class="card-head"><div><div class="card-title">Workbook calculation flow</div><div class="card-sub">Current calculation sequence</div></div><span class="pill green">15th + EOM</span></div><div class="formula-list"><div class="formula-line">Hourly rate = ((Monthly rate × 12) ÷ 260) ÷ 8</div><div class="formula-line">Gross income = Basic hours amount + Total other income</div><div class="formula-line">Net taxable income = Gross income − SSS − HDMF − PhilHealth</div><div class="formula-line">15th tax = Semi-monthly withholding lookup</div><div class="formula-line">EOM tax = Monthly tax on both cutoffs − Tax withheld on the 15th</div><div class="formula-line">13th-month minimum = Total basic salary earned in the calendar year ÷ 12</div><div class="formula-line">Net pay = Sub total + Total non-tax income / deductions</div></div><div class="verification-list"><div class="verification-item"><div><strong>Regulatory tables</strong><small>SSS, BIR withholding tax, PhilHealth and HDMF/Pag-IBIG</small></div><span class="pill amber">Verification required</span></div><div class="verification-item"><div><strong>13th-month salary base and tax ceiling</strong><small>Confirm employee coverage, CTS policy inclusions and current BIR exemption threshold each year.</small></div><span class="pill amber">Verify annually</span></div><div class="verification-item"><div><strong>Labor premiums and rounding</strong><small>Holiday, rest-day, OT, ND stacking and cutoff precision</small></div><span class="pill amber">Verification required</span></div></div></section>`}
    function holidays(){const months=['January','February','March','April','May','June','July','August','September','October','November','December'];return head('Holiday calendar','Payroll day types, local scope and source proclamations in one reviewed annual calendar.',button('+ Add holiday','teal','holiday'))+`<div class="toolbar"><div class="filters"><select class="select"><option>2026</option><option>2027</option></select><select class="select"><option>Nationwide + all locations</option></select></div><div class="filters"><span class="pill red">Regular</span><span class="pill amber">Special non-working</span><span class="pill blue">Special working</span></div></div><section class="card panel"><div class="alert-box"><span>i</span><div><strong>2026 calendar reviewed by CTS</strong><p>18 entries · source references complete · changes in a closed payroll period are blocked.</p></div></div><div style="height:16px"></div><div class="calendar">${months.map((m,i)=>`<div class="month"><h3>${m}</h3><div class="dots">${[0,3,4,5,7,10,11].includes(i)?`<i class="holiday-dot"></i>${[3,7,11].includes(i)?'<i class="holiday-dot special"></i>':''}`:'<span class="muted" style="font-size:9px">No holidays</span>'}</div></div>`).join('')}</div></section>`}
