    function overtime(){return head('Overtime approvals','Supervisor queue restricted to assigned employees, with clock validation beside every request.',button('Send reminder','','remind'))+`<div class="alert-box"><span>i</span><div><strong>Approval model awaiting CTS decision</strong><p>Employees submit requests for leader approval; notification volume is configurable.</p></div></div><div style="height:16px"></div><section class="card panel"><div class="toolbar"><div class="filters"><input class="search" placeholder="Search employee"><select class="select"><option>Pending decisions</option><option>All status</option></select></div><span class="muted">12 requests · own team only</span></div><div class="table-wrap"><table><thead><tr><th>Employee</th><th>Work date</th><th>Claimed</th><th>Clock validation</th><th>Status</th><th></th></tr></thead><tbody>${otRows.map(r=>`<tr><td><strong>${r[0]}</strong></td><td>${r[1]}</td><td class="money">${r[2]}</td><td>${r[3]}</td><td><span class="pill ${r[4]==='Approved'?'green':r[4]==='Review'?'red':'amber'}">${r[4]}</span></td><td><button class="text-link" data-action="review-ot">Review →</button></td></tr>`).join('')}</tbody></table></div></section>`}
