    function overtimeSubmission(){return head('Submit overtime','Employee self-service · file overtime against a specific work date and shift.',button('Submit request','teal','submit-ot'))+`<div class="split"><section class="card panel"><div class="form-grid"><div class="field"><label>Work date</label><input type="date" value="2026-09-04"></div><div class="field"><label>Shift</label><select><option>10:00 PM – 7:00 AM</option></select></div><div class="field"><label>Overtime start</label><input type="time" value="07:00"></div><div class="field"><label>Overtime end</label><input type="time" value="09:00"></div><div class="field" style="grid-column:1/-1"><label>Reason</label><input value="Month-end processing support"></div></div><div style="height:16px"></div><div class="alert-box"><span>i</span><div><strong>Clock data found</strong><p>TCW shows work continuing until 9:04 AM. Your 2-hour request can be validated automatically.</p></div></div></section><aside class="card panel"><div class="profile-head"><div class="profile-avatar">MS</div><div><h2>Mara Santos</h2><p>CTS-0104 · Future Analytics</p></div></div><div style="height:14px"></div><div class="summary-row"><span>Requests this cut-off</span><strong>2</strong></div><div class="summary-row"><span>Approved hours</span><strong>1.5 h</strong></div><div class="summary-row"><span>Pending hours</span><strong>2.0 h</strong></div></aside></div>`}
    function payslipHistory(){const rows=[['15 Aug 2026','01–20 Aug 2026','₱30,742.18','Delivered'],['30 Jul 2026','06–20 Jul 2026','₱29,998.45','Delivered'],['15 Jul 2026','21 Jun–05 Jul 2026','₱31,402.72','Delivered'],['30 Jun 2026','06–20 Jun 2026','₱29,710.20','Delivered']];return head('My payslips','Employee self-service · secure access to your own released payslip history.')+`<section class="card panel"><div class="profile-head"><div class="profile-avatar">MS</div><div><h2>Mara Santos</h2><p>CTS-0104 · Payslips are visible only to this employee</p></div></div><div style="height:16px"></div><div class="table-wrap"><table><thead><tr><th>Pay date</th><th>Cut-off</th><th>Net pay</th><th>Delivery</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${r[0]}</strong></td><td>${r[1]}</td><td class="money">${r[2]}</td><td><span class="pill green">${r[3]}</span></td><td><button class="text-link" data-action="download-payslip">View payslip →</button></td></tr>`).join('')}</tbody></table></div></section>`}
    function reports(){return head('Reports & outputs','Payroll cost, statutory remittance, audit evidence and payment outputs built from the approved run.',button('Export report pack','teal','export-pack'))+`<div class="rule-grid">${[['Payroll cost','Cut-off, month and client account analysis','chart'],['Statutory remittance','SSS, PhilHealth, Pag-IBIG and BIR outputs','table'],['Disbursement file','Bank-ready payment output · format to confirm','file'],['Variance report','Current vs previous cut-off, with explanations','chart'],['Audit trail','Access, corrections, rule versions and approvals','book'],['Payslip delivery','Per-employee send status and retry history','check']].map(r=>`<article class="rule-card"><div class="rule-icon">${svg(r[2])}</div><h3>${r[0]}</h3><p>${r[1]}</p><button class="text-link" data-action="open-report">Open report →</button></article>`).join('')}</div>`}
    function admin(){return head('Admin','Manage users, roles, client-account access and the audit trail without exposing payroll data unnecessarily.',button('+ Invite user','teal','invite-user'))+`<div class="split"><section class="card panel"><div class="tabs"><button class="tab active">Users & roles</button><button class="tab">Client accounts</button><button class="tab">Audit log</button></div><div class="table-wrap"><table><thead><tr><th>User</th><th>Role</th><th>Client scope</th><th>Status</th><th></th></tr></thead><tbody><tr><td><strong>Reg A.</strong></td><td>Payroll administrator</td><td>All accounts</td><td><span class="pill green">Active</span></td><td><button class="text-link" data-action="permissions">Permissions</button></td></tr><tr><td><strong>Emma C.</strong></td><td>Payroll approver</td><td>All accounts</td><td><span class="pill green">Active</span></td><td><button class="text-link" data-action="permissions">Permissions</button></td></tr><tr><td><strong>Supervisor</strong></td><td>Supervisor</td><td>Future Analytics</td><td><span class="pill green">Active</span></td><td><button class="text-link" data-action="permissions">Permissions</button></td></tr></tbody></table></div></section><aside class="card panel"><div class="card-title">Recent audit activity</div><div class="card-sub">Access and configuration changes</div><div style="height:13px"></div><div class="audit-list"><div class="audit-item"><div class="mark">R</div><div><strong>Rule version activated</strong><small>Reg A. · v2026.09</small></div><span class="muted">Yesterday</span></div><div class="audit-item"><div class="mark">U</div><div><strong>User scope changed</strong><small>Emma C. · supervisor account</small></div><span class="muted">2 days</span></div><div class="audit-item"><div class="mark">A</div><div><strong>Payroll register viewed</strong><small>Emma C. · 124 records</small></div><span class="muted">3 days</span></div></div></aside></div>`}
    const pages={'Dashboard':overview,'Timesheet import':timesheets,'Exception queue':exceptions,'Payroll run':payrollRun,'Payroll register':register,'13th-month pay':thirteenthMonth,'Run approval':approvals,'Payslip release':payslips,'Employee list':employeesPage,'Employee record':employeeRecord,'Shift schedule':shiftSchedule,'Leave requests':leaveRequests,'Rule book':rulebook,'Holiday calendar':holidays,'Reports':reports,'Admin':admin};
    const phaseOnePages=new Set(['Dashboard','Timesheet import','Payroll run','Payroll register','13th-month pay','Payslip release','Rule book','Holiday calendar']);
    function render(){renderNav();content.innerHTML=pages[active]();if(active==='Payroll register'){const nextButton=content.querySelector('[data-action="submit-approval"]');if(nextButton){nextButton.textContent='Continue to payslips';nextButton.removeAttribute('data-action');nextButton.dataset.page='Payslip release'}}if(active==='Payslip release'){const releaseButton=content.querySelector('[data-action="release"]');if(releaseButton)releaseButton.textContent='Generate & email 124 payslips';const intro=content.querySelector('.page-head p');if(intro)intro.textContent='Generate employee payslips from the computed results and automatically send them by email.';const deliveryNote=[...content.querySelectorAll('.card-sub')].find(el=>el.textContent.includes('release blocked'));if(deliveryNote)deliveryNote.textContent=`${payslipCutoff} cut-off · ready for automatic email delivery`}document.title=`${active} · CTS OS`;window.scrollTo({top:0,behavior:'smooth'})}
    function toast(title,detail='This action is not available yet.'){const n=document.getElementById('notice');n.innerHTML=`<strong>${title}</strong><small>${detail}</small>`;n.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>n.classList.remove('show'),2800)}
    document.addEventListener('click',e=>{const p=e.target.closest('[data-page]');if(p){if(!phaseOnePages.has(p.dataset.page))return;active=p.dataset.page;render();document.getElementById('sidebar').classList.remove('open');return}const a=e.target.closest('[data-action]');if(!a)return;const action=a.dataset.action;if(action==='go-run'){active='Payroll run';render()}else if(action==='profile'){selectedEmployee=a.dataset.employee||selectedEmployee;active='Employee record';render()}else if(action==='payslip-15th'){payslipCutoff='15th';render()}else if(action==='payslip-eom'){payslipCutoff='EOM';render()}else if(action==='calculate-13th'){const result=updateThirteenth();toast('13th-month pay recalculated',`${peso(result.total)} calculated from the reviewed salary base.`)}else if(action==='save-13th'){const reviewed=document.getElementById('thirteenthReviewed');if(!reviewed?.checked){toast('Review confirmation required','Confirm the salary base and employee coverage before adding this manual entry.')}else{const result=updateThirteenth();toast('Manual entry calculated',`${peso(result.total)} calculated. Saving payroll entries is not available yet.`)}}else if(action==='notify')toast('Processing status','Timesheet upload, computation and email delivery are on track.');else if(action==='help')toast('Payroll help','Follow the payroll flow from timesheet upload through payslip email.');else toast(a.textContent.trim()||'Action selected')});
    render();

/* Shared workspace controls. */
const sidebar = document.getElementById('sidebar');
const menuButton = document.getElementById('menuBtn');
const backdrop = document.getElementById('navBackdrop');
const mobileViewport = window.matchMedia('(max-width: 780px)');
let desktopNavigationExpanded = true;
function setNavigation(open, restoreFocus = false) {
  const isMobile = mobileViewport.matches;
  if (!isMobile) desktopNavigationExpanded = open;
  const expanded = open;
  sidebar.classList.toggle('open', isMobile && expanded);
  sidebar.inert = !expanded;
  document.querySelector('.app').classList.toggle('sidebar-collapsed', !isMobile && !expanded);
  backdrop.hidden = !(isMobile && expanded);
  document.querySelector('.main').inert = isMobile && expanded;
  document.body.classList.toggle('navigation-open', isMobile && expanded);
  menuButton.setAttribute('aria-expanded', String(expanded));
  menuButton.setAttribute('aria-label', expanded ? 'Collapse sidebar' : 'Expand sidebar');
  menuButton.title = expanded ? 'Collapse sidebar' : 'Expand sidebar';
  if (isMobile && expanded) sidebar.querySelector('button:not(:disabled)')?.focus();
  else if (restoreFocus) menuButton.focus();
}
menuButton.addEventListener('click', () => setNavigation(menuButton.getAttribute('aria-expanded') !== 'true'));
document.getElementById('closeNavBtn').addEventListener('click', () => setNavigation(false, true));
backdrop.addEventListener('click', () => setNavigation(false, true));
mobileViewport.addEventListener('change', () => setNavigation(mobileViewport.matches ? false : desktopNavigationExpanded));
document.addEventListener('keydown', event => {
  if (!sidebar.classList.contains('open')) return;
  if (event.key === 'Escape') setNavigation(false, true);
  if (event.key === 'Tab') {
    const buttons = [...sidebar.querySelectorAll('button:not(:disabled), a[href]')];
    const first = buttons[0], last = buttons.at(-1);
    if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last?.focus(); }
    else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first?.focus(); }
  }
});
const renderPage = render;
render = function () {
  renderPage();
  setNavigation(mobileViewport.matches ? false : desktopNavigationExpanded);
  nav.querySelector('.active')?.setAttribute('aria-current', 'page');
  content.querySelectorAll('.field').forEach((field, index) => {
    const label = field.querySelector('label');
    const input = field.querySelector('input, select');
    if (label && input) { input.id ||= `field-${index}`; label.htmlFor = input.id; }
  });
  content.querySelectorAll('input.search').forEach(input => input.setAttribute('aria-label', input.placeholder || 'Search'));
  content.querySelectorAll('select').forEach(input => {
    if (!input.labels?.length) input.setAttribute('aria-label', input.options[0]?.text || 'Filter');
  });
  content.querySelectorAll('.table-wrap').forEach(region => {
    region.tabIndex = 0;
    region.setAttribute('role', 'region');
    region.setAttribute('aria-label', `${active} table`);
  });
  content.querySelectorAll('th').forEach(cell => cell.scope = 'col');
  const heading = content.querySelector('h1');
  if (heading) { heading.tabIndex = -1; heading.focus({preventScroll: true}); }
  const hash = '#' + encodeURIComponent(active);
  if (location.hash !== hash) history.pushState(null, '', hash);
};
function restorePage() {
  let page;
  try { page = decodeURIComponent(location.hash.slice(1)); } catch { page = 'Dashboard'; }
  active = phaseOnePages.has(page) ? page : 'Dashboard';
  render();
}
window.addEventListener('popstate', restorePage);
restorePage();
